  const button = [...document.querySelectorAll('.nt-root .nt-action')].find((node) => node.textContent.includes('Undo'));
  if (!button) return null;
  const rect = button.getBoundingClientRect();
  const cx = rect.left + rect.width / 2;
  const cy = rect.top + rect.height / 2;
  const dpr = window.devicePixelRatio;
  const top = document.elementFromPoint(cx, cy);
  return {
    x: Math.round((window.screenX + cx) * dpr),
    y: Math.round((window.screenY + cy) * dpr),
    dpr,
    topElement: top ? top.className?.baseVal ?? top.className : null,
    topIsUndo: top === button || button.contains(top),
  };
})()`;
nextId += 1;
