const port = process.argv[2];
const expression = process.argv[3];
const list = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
const page = list.find((p) => p.type === "page" && p.url.startsWith("app://"));
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve) => (ws.onopen = resolve));
const pending = new Map();
let nextId = 0;
ws.onmessage = (event) => {
  const message = JSON.parse(event.data);
  if (pending.has(message.id)) {
    pending.get(message.id)(message);
    pending.delete(message.id);
  }
};
nextId += 1;
const reply = new Promise((resolve) => pending.set(nextId, resolve));
ws.send(JSON.stringify({ id: nextId, method: "Runtime.evaluate", params: { expression, returnByValue: true } }));
const result = await reply;
console.log(JSON.stringify(result.result?.result?.value ?? result.result ?? result));
ws.close();

